/** Opt-in actual-world map flow. Never enters the production bundle. */
@EventBusSubscriber(modid="rivet",value=Dist.CLIENT)
public final class WorldMapHarness {
    private static final boolean GUEST="true".equals(System.getenv("RIVET_MAP_TEST_GUEST"));
    private static final boolean SURFACE="true".equals(System.getenv("RIVET_MAP_TEST_SURFACE"));
    private static final List<VisualMatrixHarness.Frame> PROFILES=SURFACE||GUEST?List.of(new VisualMatrixHarness.Frame(0,3,false,0)):VisualMatrixHarness.flows(1,1);
    private static int step=-1,ticks,scale=1,checks,profile;private static boolean done;
    private static boolean positioned;private static long deadline;private static WorldMapScreen map;private static UUID marker;private static String captured="";
    @SubscribeEvent public static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post event) {
        String address=System.getenv("RIVET_MAP_TEST_ADDRESS");if(address==null||done)return;var mc=Minecraft.getInstance();
        try {
            if(step<0){if(!(mc.screen instanceof TitleScreen)){if(ticks++%40==0)System.out.println("RIVET_MAP_WAIT_SCREEN "+(mc.screen==null?"world":mc.screen.getClass().getSimpleName()));return;}deadline=System.currentTimeMillis()+180000;for(String key:List.of("map.title","map.search","map.scale","map.add","map.save","map.delete","map.markers"))if(Client.tr(key).getString().equals("rivet."+key))throw new IllegalStateException("Missing map translation: "+key);var data=new ServerData("Map test",address,ServerData.Type.OTHER);ConnectScreen.startConnecting(mc.screen,mc,ServerAddress.parseString(address),data,false,null);step=0;return;}
            if(System.currentTimeMillis()>deadline)throw new IllegalStateException("Map flow timed out at "+step);
            if("true".equals(System.getenv("RIVET_MAP_TEST_DISABLED"))&&mc.player!=null&&ServerMenuClient.state.has("map")){if(WorldMapClient.ready()||WorldMapClient.allowed()||DirectionCue.hasTarget())throw new IllegalStateException("Disabled map remains active");System.out.println("RIVET_MAP_DISABLED_OK");done=true;mc.stop();return;}
            if(!WorldMapClient.ready()||!WorldMapClient.markersReady())return;
            if(!positioned){if(!GUEST){mc.player.connection.sendCommand(SURFACE?"tp @s 14 83 -35":"tp @s 14 160 -35");mc.player.connection.sendCommand(SURFACE?"gamemode creative":"gamemode spectator");}positioned=true;ticks=0;return;}
            if(++ticks%16!=0)return;
            switch(step){
                case 0->{if(ticks<100)return;if(MapToolIcons.KEYS.size()!=50)throw new IllegalStateException("Wrong tool count");for(String tool:MapToolIcons.KEYS)if(!MapGlyphs.supports("map_"+tool)||Client.tr("map.tool."+tool).getString().startsWith("rivet."))throw new IllegalStateException("Missing tool or tool name: "+tool);if(!MapGlyphs.CHOICES.getFirst().equals("none"))throw new IllegalStateException("No-icon choice is not first");if(MapGlyphs.CHOICES.contains("skull"))throw new IllegalStateException("Skull is selectable");if(MapGlyphs.MARKERS.size()!=103)throw new IllegalStateException("Too few icons");for(String icon:MapGlyphs.MARKERS)if(Client.tr("map.icon."+icon).getString().startsWith("rivet."))throw new IllegalStateException("Missing icon name: "+icon);if(profile<PROFILES.size()){var frame=PROFILES.get(profile);frame.apply();scale=frame.scale();}else{UiPalette.preview(0);mc.getWindow().setWindowed(profile==PROFILES.size()?960:640,profile==PROFILES.size()?540:480);mc.options.guiScale().set(3);mc.resizeDisplay();scale=3;}map=new WorldMapScreen(null);mc.setScreen(map);for(int sample=0;sample<32;sample++){var fresh=map.point(14,-35);if(!fresh.icon().equals("none")||(fresh.color()>>>24)!=255)throw new IllegalStateException("Invalid new marker defaults");}if(GUEST&&map.canTeleport(mc.level.dimension().location().toString()))throw new IllegalStateException("Guest received teleport");bounds(map);if(!GUEST&&!map.canTeleport(mc.level.dimension().location().toString()))throw new IllegalStateException("Operator did not receive safe teleport");if(WorldMapClient.visibleTiles(mc.level.dimension().location().toString(),map.view,map.canvas().width(),map.canvas().height()).isEmpty())throw new IllegalStateException("Loaded terrain was not explored: pos="+mc.player.blockPosition()+" sky="+mc.level.canSeeSky(mc.player.blockPosition())+" ceiling="+mc.level.dimensionType().hasCeiling()+" dimension="+mc.level.dimension().location()+" status="+WorldMapClient.error());step++;}
                case 1->{var selector=(Button)map.children().stream().filter(c->c instanceof Button b&&UiActions.style(b).icon().equals("map_dimension")).findFirst().orElseThrow();String initial=map.selectedDimension();if(!initial.equals(mc.level.dimension().location().toString()))throw new IllegalStateException("Map did not open in player dimension");selector.onPress();if(!(mc.screen instanceof ChoicePopup))throw new IllegalStateException("Dimension must be dropdown");bounds(mc.screen);var dimensionButtons=mc.screen.children().stream().filter(c->c instanceof Button).map(c->(Button)c).toList();var other=dimensionButtons.stream().filter(b->!b.getMessage().getString().startsWith("✓ ")).findFirst().orElseThrow();other.onPress();if(mc.screen!=map||map.selectedDimension().equals(initial))throw new IllegalStateException("Dimension selection failed");selector=(Button)map.children().stream().filter(c->c instanceof Button b&&UiActions.style(b).icon().equals("map_dimension")).findFirst().orElseThrow();selector.onPress();pressComponent(mc.screen,dev.abros.rivet.network.DimensionLabels.name(initial).getString());if(!map.selectedDimension().equals(initial))throw new IllegalStateException("Dimension return failed");double x=map.width*.65,y=map.height*.65;double block=map.view.worldX(x,map.canvas().x()+map.canvas().width()/2d);map.mouseScrolled(x,y,0,2);if(Math.abs(block-map.view.worldX(x,map.canvas().x()+map.canvas().width()/2d))>1e-6)throw new IllegalStateException("Zoom moved cursor anchor");map.mouseClicked(x,y,0);map.mouseDragged(x+20,y+20,0,20,20);map.mouseReleased(x+20,y+20,0);press(map,"map.ruler");double rx=map.width*.4,ry=map.height*.45;map.mouseClicked(rx,ry,0);map.mouseReleased(rx,ry,0);map.mouseClicked(rx+30,ry+40,0);map.mouseReleased(rx+30,ry+40,0);if(Math.abs(map.measuredDistance()-50/map.view.zoom())>1e-6)throw new IllegalStateException("Ruler distance incorrect");double measured=map.measuredDistance();map.view.pan(8,6);map.mouseScrolled(rx,ry,0,1);if(map.measuredDistance()!=measured)throw new IllegalStateException("Ruler changed after pan/zoom");checks+=2;step=7;}
                case 7->{map.mouseClicked(map.width*.4,map.height*.45,1);if(!Double.isNaN(map.measuredDistance())||!map.measuring())throw new IllegalStateException("RMB did not clear ruler");map.keyPressed(256,0,0);if(map.measuring())throw new IllegalStateException("Escape did not exit ruler");double centerX=map.view.x(),centerZ=map.view.z();press(map,"map.markers");bounds(map);if(map.canvas().x()!=0||map.canvas().width()!=map.width||map.canvas().height()!=map.height||map.view.x()!=centerX||map.view.z()!=centerZ)throw new IllegalStateException("Overlay moved or resized the canvas");checks+=2;step=2;}
                case 2->{map.keyPressed(256,0,0);if(mc.screen!=map)throw new IllegalStateException("Escape should close drawer first");press(map,"map.add");bounds(mc.screen);if(mc.screen!=map||!map.markerOpen())throw new IllegalStateException("Create must use right panel");var abandoned=map.draftMarker();if(abandoned==null||map.visibleMarkers().stream().noneMatch(m->m.id().equals(abandoned.id()))||WorldMapClient.markers().stream().anyMatch(m->m.id().equals(abandoned.id())))throw new IllegalStateException("New marker preview missing or persisted early");dragDraft(false);press(map,"cancel");if(map.markerOpen()||map.visibleMarkers().stream().anyMatch(m->m.id().equals(abandoned.id())))throw new IllegalStateException("Cancelled new marker remained on map");press(map,"map.add");dragDraft(false);for(var child:mc.screen.children())if(child instanceof EditBox input&&input.getMessage().getString().equals(Client.tr("map.name").getString())){if(!input.getValue().isEmpty())throw new IllegalStateException("New marker name must start empty");input.setValue("Native map marker "+profile);}press(map,"map.color.green");int nameY=map.children().stream().filter(c->c instanceof EditBox).map(c->((EditBox)c).getY()).findFirst().orElseThrow();map.revealIcon("logpile");bounds(map);press(map,"map.icon.logpile");var nameBox=map.children().stream().filter(c->c instanceof EditBox).map(c->(EditBox)c).findFirst().orElseThrow();if(nameBox.getY()!=nameY||!nameBox.getValue().equals("Native map marker "+profile))throw new IllegalStateException("Icon scrolling moved or lost name field");if(map.children().stream().filter(c->c instanceof UiColorSwatch).count()!=12)throw new IllegalStateException("Icon scrolling hid colours");checks+=2;map.revealIcon("castle");bounds(map);press(map,"map.icon.castle");var preview=map.draftMarker();if(!preview.icon().equals("castle")||preview.color()!=0xff87d59c||map.visibleMarkers().stream().filter(m->m.id().equals(preview.id())).count()!=1)throw new IllegalStateException("Preview did not follow icon/colour changes");cancelDrag();step++;}
                case 3->{categoryFlow();press(mc.screen,"map.save");if(mc.screen!=map)throw new IllegalStateException("Save lost map view");var saved=WorldMapClient.markers().stream().filter(m->m.name().equals("Native map marker "+profile)).findFirst().orElseThrow();if(!saved.icon().equals("castle")||saved.color()!=0xff87d59c)throw new IllegalStateException("Icon or colour was not saved");marker=saved.id();if(!map.markerOpen())throw new IllegalStateException("Save must show marker card");map.closeMarker();double mx=map.view.screenX(saved.x()+.5,map.width/2d),my=map.view.screenZ(saved.z()+.5,map.height/2d);map.mouseClicked(mx,my,1);if(!(mc.screen instanceof UiContextPopup))throw new IllegalStateException("Right-click did not open context menu");bounds(mc.screen);var labels=mc.screen.children().stream().filter(c->c instanceof Button).map(c->((Button)c).getMessage().getString()).toList();if(!labels.contains(Client.tr("map.add").getString())||!labels.contains(Client.tr("map.edit").getString())||!labels.contains(Client.tr("map.delete").getString())||labels.contains(Client.tr("map.teleportMarker").getString())!=map.canTeleport(saved.dimension()))throw new IllegalStateException("Wrong waypoint actions or teleport permissions: "+labels);step++;}
                case 4->{mc.screen.keyPressed(256,0,0);if(mc.screen!=map)throw new IllegalStateException("Context Escape lost map");map.mouseClicked(map.width-4,map.height-40,1);if(!(mc.screen instanceof UiContextPopup))throw new IllegalStateException("Edge context missing");bounds(mc.screen);mc.screen.keyPressed(256,0,0);if(mc.screen!=map)throw new IllegalStateException("Edge context lost map");var saved=WorldMapClient.markers().stream().filter(m->m.id().equals(marker)).findFirst().orElseThrow();map.openMarker(saved,false);step++;}
                case 5->{bounds(mc.screen);if(mc.screen!=map||!map.markerOpen())throw new IllegalStateException("Card must be right overlay");var original=map.draftMarker();dragDraft(true);for(var child:map.children())if(child instanceof EditBox input)input.setValue("Unsaved edit");press(map,"cancel");if(WorldMapClient.markers().stream().anyMatch(m->m.id().equals(marker)&&m.name().equals("Unsaved edit")))throw new IllegalStateException("Cancel persisted draft");if(map.children().stream().filter(c->c instanceof EditBox).map(c->((EditBox)c).getValue()).anyMatch("Unsaved edit"::equals))throw new IllegalStateException("Cancel did not restore fields");if(!map.draftMarker().equals(original))throw new IllegalStateException("Cancel did not restore marker position");dragDraft(true);var moved=map.draftMarker();press(map,"map.save");var persisted=WorldMapClient.markers().stream().filter(m->m.id().equals(marker)).findFirst().orElseThrow();if(!persisted.equals(moved))throw new IllegalStateException("Move was not saved");press(mc.screen,"map.navigate");if(mc.screen!=null||!DirectionCue.hasTarget())throw new IllegalStateException("Navigation must close map and retain target");mc.setScreen(map);press(map,"map.stop");if(DirectionCue.hasTarget())throw new IllegalStateException("Map stop did not cancel route");var stored=WorldMapClient.markers().stream().filter(m->m.id().equals(marker)).findFirst().orElseThrow();map.openMarker(stored,false);press(mc.screen,"map.delete");if(!(mc.screen instanceof UiConfirmDialog))throw new IllegalStateException("Delete requires confirmation");step++;}
                case 6->{var confirm=(Button)mc.screen.children().stream().filter(c->c instanceof Button b&&b.active&&UiActions.style(b).tone()==UiActions.Tone.DANGER).findFirst().orElseThrow();confirm.onPress();if(WorldMapClient.markers().stream().anyMatch(m->m.id().equals(marker)))throw new IllegalStateException("Marker deletion failed");if(mc.screen!=map)throw new IllegalStateException("Deletion lost map");map.onClose();if(++profile<=PROFILES.size()+1){ticks=0;step=0;}else{System.out.println("RIVET_MAP_UI_OK checks="+checks+(GUEST?" scales=3 guest=true":SURFACE?" scales=3 surface=true":" scales=1,2,3 profiles=default,light,contrast")+" compact=true actualTerrain=true");done=true;mc.stop();}}
            }
        }catch(Throwable ex){System.out.println("RIVET_MAP_UI_FAILED step="+step+" scale="+scale);ex.printStackTrace();done=true;mc.stop();}
    }
    @SubscribeEvent public static void render(net.neoforged.neoforge.client.event.ScreenEvent.Render.Post event){if(System.getenv("RIVET_MAP_TEST_ADDRESS")==null||done)return;String directory=System.getenv("RIVET_MAP_SCREENSHOTS");if(directory!=null&&Minecraft.getInstance().screen!=null&&ticks%16==1&&!captured.equals(profile+"-"+step)){captured=profile+"-"+step;var folder=new java.io.File(directory);folder.mkdirs();UiCaptureHarness.grab(folder,"map-"+captured+".png",Minecraft.getInstance().getMainRenderTarget(),m->{});}}
    private static Screen details(){var mc=Minecraft.getInstance();if(map.children().stream().anyMatch(c->c instanceof Button b&&b.getMessage().equals(Client.tr("map.details"))))press(map,"map.details");return mc.screen;}
    private static void coordinate(Screen screen,String axis,String value){var field=(EditBox)screen.children().stream().filter(c->c instanceof EditBox e&&e.getMessage().getString().equals(axis)).findFirst().orElseThrow();field.setValue(value);}
    private static void categoryFlow(){var mc=Minecraft.getInstance();Screen detail=details();bounds(detail);press(detail,"map.categories");var categories=(MapCategoriesScreen)mc.screen;bounds(categories);String categoryName="Native category "+profile;categories.revealRow(0);categories.rebuildWidgets();((EditBox)categories.children().stream().filter(c->c instanceof EditBox).findFirst().orElseThrow()).setValue(categoryName);categories.revealRow(1);categories.rebuildWidgets();press(categories,"map.visibleMap");categories.revealRow(3);categories.rebuildWidgets();bounds(categories);press(categories,"map.save");var category=WorldMapClient.categories().stream().filter(c->c.name().equals(categoryName)).findFirst().orElseThrow();if(category.mapVisible()||!category.minimapVisible())throw new IllegalStateException("Category visibility not saved");categories.onClose();if(mc.screen!=detail)throw new IllegalStateException("Categories lost draft parent");pressComponent(detail,Client.tr("map.uncategorized").getString()+" ▾");bounds(mc.screen);pressComponent(mc.screen,categoryName);if(mc.screen!=detail)throw new IllegalStateException("Category selection lost details");press(detail,"map.visibleMinimapShort");int x=map.draftMarker().x()+1;coordinate(detail,"X","30000001");if(detail!=map)detail.onClose();press(map,"map.save");if(WorldMapClient.markers().stream().anyMatch(m->m.id().equals(map.draftMarker().id())))throw new IllegalStateException("Invalid coordinate was saved");detail=details();coordinate(detail,"X",""+x);if(detail!=map)detail.onClose();press(map,"map.save");var saved=map.draftMarker();if(saved.x()!=x||!saved.category().equals(category.id().toString())||saved.minimapVisible()||WorldMapClient.visible(saved,false)||WorldMapClient.visible(saved,true))throw new IllegalStateException("Marker category, coordinates or visibility wrong");WorldMapClient.category(new MapCategory(category.id(),categoryName+" renamed",true,true));if(!WorldMapClient.visible(saved,false)||WorldMapClient.visible(saved,true))throw new IllegalStateException("Category rename lost marker binding");map.closeMarker();press(map,"map.markers");var search=(EditBox)map.children().stream().filter(c->c instanceof EditBox).findFirst().orElseThrow();search.setValue(categoryName+" renamed");map.tick();bounds(map);if(map.children().stream().noneMatch(c->c instanceof Button b&&b.getMessage().getString().equals(saved.name())))throw new IllegalStateException("Search did not find category marker");pressComponent(map,Client.tr("map.allCategories").getString()+" ▾");pressComponent(mc.screen,categoryName+" renamed");bounds(map);search=(EditBox)map.children().stream().filter(c->c instanceof EditBox).findFirst().orElseThrow();search.setValue("absent marker query");map.tick();if(map.children().stream().anyMatch(c->c instanceof Button b&&b.getMessage().getString().equals(saved.name())))throw new IllegalStateException("Live search failed to filter marker");search=(EditBox)map.children().stream().filter(c->c instanceof EditBox).findFirst().orElseThrow();search.setValue("");map.tick();map.keyPressed(256,0,0);map.openMarker(saved,false);checks+=3;detail=details();press(detail,"map.visibleMinimapShort");if(detail!=map)detail.onClose();press(map,"map.save");WorldMapClient.deleteCategory(category.id());if(!WorldMapClient.visible(map.draftMarker(),false)||!WorldMapClient.visible(map.draftMarker(),true)||!WorldMapClient.categoryName(map.draftMarker().category()).equals(Client.tr("map.uncategorized").getString()))throw new IllegalStateException("Category removal hid or removed markers");checks+=7;
    }
    private static void dragDraft(boolean existing){
        var before=map.draftMarker();double vx=map.view.x(),vz=map.view.z();
        double x=map.view.screenX(before.x()+.5,map.width/2d),y=map.view.screenZ(before.z()+.5,map.height/2d);
        map.mouseClicked(x,y,0);map.mouseDragged(x+8,y+8,0,8,8);map.mouseReleased(x+8,y+8,0);
        var after=map.draftMarker();
        if(after.x()!=(int)Math.floor(before.x()+.5+8/map.view.zoom())||after.z()!=(int)Math.floor(before.z()+.5+8/map.view.zoom())||map.view.x()!=vx||map.view.z()!=vz)throw new IllegalStateException("Dragging marker moved map or wrong coordinates: profile="+profile+" viewport="+map.width+"x"+map.height+" before="+before+" after="+after);
        var tile=WorldMapClient.tile(after.dimension(),Math.floorDiv(after.x(),16),Math.floorDiv(after.z(),16));
        if(tile!=null&&tile.color(Math.floorMod(after.x(),16),Math.floorMod(after.z(),16))!=0&&after.y()!=tile.height(Math.floorMod(after.x(),16),Math.floorMod(after.z(),16))+1)throw new IllegalStateException("Moved marker height is stale");
        if(existing&&WorldMapClient.markers().stream().filter(m->m.id().equals(before.id())).noneMatch(before::equals))throw new IllegalStateException("Dragging saved changes before Save");
        checks+=2;
    }
    private static void cancelDrag(){
        var before=map.draftMarker();double x=map.view.screenX(before.x()+.5,map.width/2d),y=map.view.screenZ(before.z()+.5,map.height/2d);
        map.mouseClicked(x,y,0);map.mouseDragged(x+8,y+8,0,8,8);map.mouseReleased(map.markerBox().x()+10,map.markerBox().y()+14,0);
        if(!map.draftMarker().equals(before))throw new IllegalStateException("Drop over panel did not cancel move");
        map.mouseClicked(x,y,0);map.mouseDragged(x+8,y+8,0,8,8);map.keyPressed(256,0,0);map.mouseReleased(x+8,y+8,0);
        if(!map.markerOpen()||!map.draftMarker().equals(before))throw new IllegalStateException("Escape did not cancel move");
        map.mouseClicked(x,y,0);map.mouseReleased(x,y,0);
        if(!map.draftMarker().equals(before))throw new IllegalStateException("Click reset draft fields");checks+=3;
    }
    private static void pressComponent(Screen screen,String label){((Button)screen.children().stream().filter(c->c instanceof Button b&&b.getMessage().getString().equals(label)).findFirst().orElseThrow()).onPress();checks++;}
    private static void press(Screen screen,String key){if(screen instanceof WorldMapScreen map&&key.equals("map.export")){MapUiHarnessActions.context(map);screen=net.minecraft.client.Minecraft.getInstance().screen;}String label=Client.tr(key).getString();var button=(Button)screen.children().stream().filter(c->c instanceof Button b&&b.active&&b.getMessage().getString().equals(label)).findFirst().orElseThrow(()->new IllegalStateException("Missing "+key));button.onPress();checks++;}
    private static void bounds(Screen screen){var widgets=screen.children().stream().filter(c->c instanceof AbstractWidget w&&w.visible).map(c->(AbstractWidget)c).toList();for(var a:widgets){if(a.getX()<0||a.getY()<0||a.getX()+a.getWidth()>screen.width||a.getY()+a.getHeight()>screen.height)throw new IllegalStateException("Map widget outside viewport: "+a.getMessage());for(var b:widgets)if(a!=b&&a.getX()<b.getX()+b.getWidth()&&b.getX()<a.getX()+a.getWidth()&&a.getY()<b.getY()+b.getHeight()&&b.getY()<a.getY()+a.getHeight())throw new IllegalStateException("Map widgets overlap: "+a.getMessage()+" / "+b.getMessage());}checks++;}
}
